contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address staker) public {
        require(staker != address(0), "zero staker");
        require(amount > 0, "zero amount");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(staker);

        // fund this contract with staking tokens so it can stake for staker
        // (calling a view/pure function on c is allowed inside require; 
        //  calling transferFrom on the staking token is a direct external call 
        //  that is not on c, so we do it directly)
        require(c.stakingToken().balanceOf(address(this)) >= amount, "insufficient funds");
        c.stakingToken().transfer(address(c), amount);

        c.stakeFor(staker, amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(staker);

        assert(supplyAfter == supplyBefore + amount && balanceAfter == balanceBefore + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, address funder, uint256 amount) public {
        require(amount > 0, "zero amount");
        require(funder != address(0), "zero funder");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(staker);

        bool funded = c.stakingToken().transferFrom(funder, address(c), amount);

        bool staked = false;
        if (funded) {
            try c.stakeFor(staker, amount) {
                staked = true;
            } catch {}
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(staker);

        if (staked) {
            assert(supplyAfter == supplyBefore + amount);
            assert(balanceAfter == balanceBefore + amount);
        } else {
            assert(supplyAfter == supplyBefore);
            assert(balanceAfter == balanceBefore);
        }
    }
}

