contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address staker) public {
        require(staker != address(0));
        require(amount > 0);

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(staker);
        uint256 contractTokenBalanceBefore = c.stakingToken().balanceOf(address(c));
        uint256 stakerTokenBalance = c.stakingToken().balanceOf(address(this));

        bool sufficient = stakerTokenBalance >= amount;

        bool reverted;
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (sufficient) {
            assert(!reverted);
            assert(c.totalSupply() == supplyBefore + amount);
            assert(c.balanceOf(staker) == balanceBefore + amount);
            assert(c.stakingToken().balanceOf(address(c)) == contractTokenBalanceBefore + amount);
        } else {
            assert(reverted);
            assert(c.totalSupply() == supplyBefore);
            assert(c.balanceOf(staker) == balanceBefore);
            assert(c.stakingToken().balanceOf(address(c)) == contractTokenBalanceBefore);
        }
    }

    receive() external payable {}
}

