contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardDistributor_, address rewardToken, uint256 amount) public {
        // Set the reward distributor to the zero address so the test contract can never be the distributor.
        c.setRewardDistributor(rewardDistributor_);

        // Ensure the reward token is registered so the call would otherwise be valid.
        c.addReward(rewardToken);

        // Attempt to notify a reward amount; this should revert because the test contract is not the distributor.
        bool reverted;
        if (amount > 0) {
            try c.notifyRewardAmount(rewardToken, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true;
        }

        assert(reverted);
    }
}

