contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        // Use a nonzero stake amount; the contract requires amount > 0.
        require(amount > 0);

        // The test contract must own enough staking tokens and have approved c to spend them.
        // We assume the constructor/deployment setup has already funded this contract and
        // approved c; the test only needs to drive stake.
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 tokenBefore = c.stakingToken().balanceOf(address(c));

        // stash totalSupply before the state-changing call
        c.stake(amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 tokenAfter = c.stakingToken().balanceOf(address(c));

        assert(
            supplyAfter == supplyBefore + amount &&
            balanceAfter == balanceBefore + amount &&
            tokenAfter == tokenBefore + amount
        );
    }

    receive() external payable {}
}

