            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(address(this));

        // General rule: a successful withdraw of `amount` must reduce the caller's
        // staked balance by exactly `amount`, and withdrawing more than the current
        // balance must be rejected (revert).
        assert(
            (reverted && beforeBalance < amount) ||
            (!reverted && beforeBalance >= amount && afterBalance == beforeBalance - amount)
        );
    }
}

