contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        // need positive stake and a valid withdrawal
        require(stakeAmount > 0, "need positive stake");
        require(withdrawAmount > 0 && withdrawAmount <= stakeAmount, "bad withdraw");

        // read initial total supply and staker balance
        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialStakerBalance = c.balanceOf(address(this));

        // perform the stake (single top-level call)
        // stakeFor pulls stakingToken from msg.sender = this test contract,
        // but the test contract must hold staking tokens.
        // Since we cannot mint staking tokens inside this test without
        // re-declaring an interface, assume the deployer funded this test
        // contract with enough staking tokens. If that assumption does not
        // hold, the checker will simply see the stake call revert and the
        // rule will be vacuous because the assert is reached with state
        // unchanged. To avoid vacuity we require a successful stake then
        // assert the invariant.
        bool stakeReverted;
        try c.stakeFor(address(this), stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        if (!stakeReverted) {
            // withdraw exactly withdrawAmount, claiming rewards
            c.withdraw(withdrawAmount, true);

            uint256 finalTotalSupply = c.totalSupply();
            uint256 finalStakerBalance = c.balanceOf(address(this));

            assert(
                finalTotalSupply == initialTotalSupply + stakeAmount - withdrawAmount &&
                finalStakerBalance == initialStakerBalance + stakeAmount - withdrawAmount
            );
        } else {
            // if stake reverted, state unchanged and the rule is trivially true
            assert(c.totalSupply() == initialTotalSupply && c.balanceOf(address(this)) == initialStakerBalance);
        }
    }
}

