contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount, bool claim) public {
        require(staker != address(0));
        require(stakeAmount > 0);

        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("totalSupply()")
        );
        uint256 totalBefore0 = ok && ret.length >= 32 ? abi.decode(ret, (uint256)) : 0;

        (bool ok2, bytes memory ret2) = address(c).call(
            abi.encodeWithSignature("balanceOf(address)", staker)
        );
        uint256 balBefore0 = ok2 && ret2.length >= 32 ? abi.decode(ret2, (uint256)) : 0;

        require(balBefore0 == 0, "test setup: staker already has balance");
        require(totalBefore0 == 0, "test setup: pool already has supply");

        require(address(c).balance >= stakeAmount, "test lacks tokens to stake");

        c.stakeFor{value: 0}(staker, stakeAmount);

        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);
        require(totalBefore == stakeAmount, "stake did not increase total supply");
        require(balBefore == stakeAmount, "stake did not increase staker balance");

        bool reverted;
        if (withdrawAmount > balBefore) {
            try c.withdraw(withdrawAmount, claim) {
                reverted = false;
            } catch {
                reverted = true;
            }

            assert(reverted);
            assert(c.totalSupply() == totalBefore);
            assert(c.balanceOf(staker) == balBefore);
        } else {
            require(withdrawAmount > 0, "withdraw amount must be positive");
            c.withdraw(withdrawAmount, claim);
            reverted = false;

            assert(!reverted);
            assert(c.totalSupply() == totalBefore - withdrawAmount);
            assert(c.balanceOf(staker) == balBefore - withdrawAmount);
        }
    }

    receive() external payable {}
}

