        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(staker);

        // Invariant must hold on the initial state.
        assert(balanceBefore <= supplyBefore);

        // Try a state-changing call through the public surface to see the invariant persists.
        // withdrawAll(false) reverts if staker has no balance, otherwise reduces both.
        bool reverted;
        try c.withdrawAll(false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(staker);

        // General rule: a single account can never hold more than the total supply,
        // both before and after any withdraw attempt.
        assert(supplyAfter >= balanceAfter && supplyAfter <= supplyBefore);
    }

    receive() external payable {}
}

