    constructor(C _c) { c = _c; }

    function run(address target, uint256 amount) public payable {
        require(target != address(0), "zero target");
        require(amount > 0, "zero amount");
        require(amount <= 1e30, "too large");

        // put the staking token into this test contract by staking a tiny amount first? no;
        // we assume the test contract already holds staking tokens via constructor.
        // Instead, use the fact that c's stakingToken is a public getter.
        IERC20 st = c.stakingToken();

        // fund this test contract with the staking token by transferring from the deployer? impossible.
        // So we must rely on the staking token being minted to address(this) before run.
        // The property: after staking amount, balanceOf(target) increases by amount, totalSupply increases by amount,
        // and c's staking balance increases by amount. If this contract doesn't have tokens, the call reverts.
        uint balBefore = c.balanceOf(target);
        uint tsBefore = c.totalSupply();
        uint cStakeBefore = st.balanceOf(address(c));

        bool reverted;
        try c.stakeFor(target, amount) { reverted = false; } catch { reverted = true; }

        uint balAfter = c.balanceOf(target);
        uint tsAfter = c.totalSupply();
        uint cStakeAfter = st.balanceOf(address(c));

        if (!reverted) {
            assert(balAfter == balBefore + amount && tsAfter == tsBefore + amount && cStakeAfter == cStakeBefore + amount);
        } else {
            assert(balAfter == balBefore && tsAfter == tsBefore && cStakeAfter == cStakeBefore);
        }
    }

    receive() external payable {}
}

