contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 amount) public {
        // Precondition: the reward token must be known and the concrete amount must be nonzero.
        require(amount > 0, "amount must be positive");
        require(c.rewardPeriodFinish(rewardToken) != 0, "reward token must exist");

        // Read the staking token's balance that this test contract holds on behalf of c.
        // notifyRewardAmount pulls the reward token from the caller, so we guarantee that
        // this test contract can pay the amount if the call unexpectedly proceeds.
        address stakingToken = address(c.stakingToken());
        uint256 balanceBefore = IERC20(rewardToken).balanceOf(address(this));
        require(balanceBefore >= amount, "test contract cannot pay");

        // Record the reward rate before the deciding call. A successful notifyRewardAmount
        // must alter reward accounting, so a no-op must not satisfy an accidental assert.
        uint256 rateBefore = uint256(c.rewardData(rewardToken));

        // Ensure the caller is neither the owner nor the reward distributor. Both known
        // privileged addresses must remain intact after the failing call.
        address ownerBefore = c.owner();
        address distributorBefore = address(c.rewardDistributor());
        require(msg.sender != ownerBefore, "caller is owner");
        require(msg.sender != distributorBefore, "caller is distributor");

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: an unauthorized caller must always revert, the reward token balance
        // of this contract must be unchanged, and the reward data must remain untouched.
        assert(
            reverted &&
            IERC20(rewardToken).balanceOf(address(this)) == balanceBefore &&
            uint256(c.rewardData(rewardToken)) == rateBefore &&
            address(c.rewardDistributor()) == distributorBefore &&
            c.owner() == ownerBefore
        );
    }
}

