    function run(uint256 amount) public {
        require(amount > 0, "amount must be positive");

        // Setup is minimal: only run when the staking token balance of this test
        // contract is sufficient for the prospective stake call. For a fresh C,
        // totalSupply() is 0 even if balanceOf(this) is 0, so this also permits
        // amount when balanceOf(this) >= amount.
        bool canStake = c.stakingToken().balanceOf(address(this)) >= amount;

