        require(canStake, "insufficient staking token balance");

        c.stake(amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        // General rule: a successful stake of `amount` increases both the
        // staker's balance and totalSupply by exactly `amount`.
        assert(supplyAfter == supplyBefore + amount && balAfter == balBefore + amount);
    }

    receive() external payable {}
}

