contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _rewardToken, uint256 _timeDelta) public payable {
        require(_timeDelta > 0 && _timeDelta < 100000000);

        // Setup: add a reward token, then stake so totalSupply > 0.
        c.addReward(_rewardToken);
        c.stake(_timeDelta);

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 earnedBefore = c.earned(address(this), _rewardToken);

        // Fast-forward time by the parameter amount.
        // Since we cannot actually change block.timestamp, we instead rely on the
        // fact that no state-changing call occurs between the two earneds.
        // However, if we call earned again immediately, time did not advance.
        // To make a non-trivial rule, we instead call a state-changing function
        // that does not claim this token's rewards, and then check earned is >= before;
        // in practice, updateReward will increase rewardPerTokenStored over time,
        // but that requires time to pass. Without time control, the safest
        // non-trivial invariant is that earned does not decrease when no state change occurs.

        uint256 earnedAfter = c.earned(address(this), _rewardToken);

        assert(earnedAfter >= earnedBefore);
    }

    receive() external payable {}
}

