contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 withdrawAmount, bool useWithdrawAll) public {
        require(stakeAmount > 0, "stake amount must be positive");

        uint256 beforeTestBal = c.balanceOf(address(this));
        uint256 beforeTestSupply = c.totalSupply();

        c.stake(stakeAmount);

        uint256 afterStakeBal = c.balanceOf(address(this));
        uint256 afterStakeSupply = c.totalSupply();

        bool reverted;
        uint256 afterBal;
        uint256 afterSupply;

        if (useWithdrawAll) {
            c.withdrawAll(false);
            afterBal = c.balanceOf(address(this));
            afterSupply = c.totalSupply();
            reverted = false;
        } else {
            require(withdrawAmount > 0, "withdraw amount must be positive");
            try c.withdraw(withdrawAmount, false) {
                reverted = false;
                afterBal = c.balanceOf(address(this));
                afterSupply = c.totalSupply();
            } catch {
                reverted = true;
                afterBal = c.balanceOf(address(this));
                afterSupply = c.totalSupply();
            }
        }

        assert(
            afterStakeBal == beforeTestBal + stakeAmount &&
            afterStakeSupply == beforeTestSupply + stakeAmount &&
            (
                (useWithdrawAll && !reverted && afterBal == 0 && afterSupply + afterStakeBal == afterStakeSupply) ||
                (!useWithdrawAll && reverted && afterBal == afterStakeBal && afterSupply == afterStakeSupply) ||
                (!useWithdrawAll && !reverted && withdrawAmount <= afterStakeBal && afterBal + withdrawAmount == afterStakeBal && afterSupply + withdrawAmount == afterStakeSupply)
            )
        );
    }

    receive() external payable {}
}
